// This will now correctly use the incoming data.
let successfulJobs = [];
try {
  // The 'const' keyword has been removed from the line below.
  successfulJobs = items;
} catch (error) {
  console.log("An error occurred while assigning items.", error);
}

// Get the initial data from the Webhook trigger node for all final steps.
const webhookData = $('Webhook').item.json;
const userEmail = webhookData.body.email;
const userName = webhookData.body.name;
const transactionId = webhookData.body.transactionId;
const submissionId = webhookData.body.submissionId;

// If no jobs were processed successfully, set a 'failure' status and pass the data along.
if (successfulJobs.length === 0) {
  return [{
    json: {
      status: 'failure',
      reason: 'No matching jobs were found to process after filtering.',
      userEmail: userEmail,
      userName: userName,
      transactionId: transactionId,
      submissionId: submissionId
    }
  }];
}

// If we have successful jobs, proceed to build the HTML email.
let emailHtml = `
<html>
  <body style="font-family: Arial, sans-serif; line-height: 1.6; color: #333;">
    <p>Hi ${userName},</p>
    <p>Your JobMonkey request is complete! Here are the tailored resumes and cover letters for the ${successfulJobs.length} jobs that were successfully processed:</p>
`;

// Loop through each successful job and add its details to the email body.
let jobCounter = 1;
for (const job of successfulJobs) {
  const { json } = job;
  emailHtml += `
    <hr style="margin: 30px 0; border: 1px solid #ccc;">
    <h2>Job #${jobCounter}: ${json.job_title} at ${json.company_name}</h2>
    <p><strong>Job URL:</strong> <a href="${json.job_url}">${json.job_url}</a></p>

    <h3>Your Cover Letter:</h3>
    <div style="background: #f9f9f9; padding: 15px; border: 1px solid #eee; border-radius: 8px; margin-bottom: 15px;">
      ${json.cover_letter}
    </div>

    <h3>Your Tailored Resume:</h3>
    <div style="background: #f9f9f9; padding: 15px; border: 1px solid #eee; border-radius: 8px;">
      ${json.tailored_resume}
    </div>
  `;
  jobCounter++;
}

emailHtml += `
    <hr style="margin-top: 30px;">
    <p>Good luck with your applications!</p>
    <p>The JobMonkey Team</p>
  </body>
</html>
`;

// Return the final data needed for the next steps.
return [{
  json: {
    finalEmailBody: emailHtml,
    userEmail: userEmail,
    userName: userName,
    status: 'success',
    submissionId: submissionId
  }
}];

// Set the maximum number of jobs you want to process.
const maxJobs = 10;

// This line takes the full list of jobs and returns only the first 15.
return items.slice(0, maxJobs);
